package com.pranit.productsupport.core.repository;
import com.pranit.productsupport.core.domain.Ticket; import java.util.Optional; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository;
